public class Solution {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        int[] xs = new int[n];
        int[] ys = new int[n];

        Map<Integer, List<Integer>> rows = new HashMap<>();
        Map<Integer, List<Integer>> cols = new HashMap<>();

        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            xs[i] = Integer.parseInt(parts[0]);
            ys[i] = Integer.parseInt(parts[1]);
            rows.computeIfAbsent(xs[i], k -> new ArrayList<>()).add(i);
            cols.computeIfAbsent(ys[i], k -> new ArrayList<>()).add(i);
        }

        List<Integer>[] adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();

        for (List<Integer> list : rows.values()) {
            for (int i = 0; i < list.size(); i++) {
                for (int j = i + 1; j < list.size(); j++) {
                    int a = list.get(i), b = list.get(j);
                    adj[a].add(b);
                    adj[b].add(a);
                }
            }
        }
        for (List<Integer> list : cols.values()) {
            for (int i = 0; i < list.size(); i++) {
                for (int j = i + 1; j < list.size(); j++) {
                    int a = list.get(i), b = list.get(j);
                    adj[a].add(b);
                    adj[b].add(a);
                }
            }
        }

        int[] compSize = new int[n];
        boolean[] visited = new boolean[n];
        int[] compId = new int[n];
        Arrays.fill(compId, -1);
        int compCnt = 0;
        List<Integer> sizes = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                Queue<Integer> q = new LinkedList<>();
                q.add(i);
                visited[i] = true;
                int size = 0;
                List<Integer> members = new ArrayList<>();
                while (!q.isEmpty()) {
                    int u = q.poll();
                    members.add(u);
                    size++;
                    for (int v : adj[u]) {
                        if (!visited[v]) {
                            visited[v] = true;
                            q.add(v);
                        }
                    }
                }
                for (int u : members) compId[u] = compCnt;
                sizes.add(size);
                compCnt++;
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int sz = sizes.get(compId[i]);
            sb.append(sz == 1 ? 0 : sz - 1).append("\n");
        }
        System.out.print(sb);
    }
}

