public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long x = 0;
            while (c > ' ') {
                x = x * 10 + (c - '0');
                c = read();
            }
            return x * sgn;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class DSU {
        int[] p, sz;
        int edges;
        DSU(int n) {
            p = new int[n];
            sz = new int[n];
            for (int i = 0; i < n; i++) {
                p[i] = i;
                sz[i] = 1;
            }
        }
        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }
        void union(int a, int b) {
            a = find(a); b = find(b);
            if (a == b) return;
            if (sz[a] < sz[b]) { int t = a; a = b; b = t; }
            p[b] = a;
            sz[a] += sz[b];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int N;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        long[] X = new long[N];
        long[] Y = new long[N];
        for (int i = 0; i < N; i++) {
            X[i] = fs.nextLong();
            Y[i] = fs.nextLong();
        }

        // Coordinate compression by used rows/cols
        long[] xs = X.clone();
        long[] ys = Y.clone();
        Arrays.sort(xs);
        Arrays.sort(ys);

        HashMap<Long, Integer> xId = new HashMap<>(N * 2);
        HashMap<Long, Integer> yId = new HashMap<>(N * 2);
        for (int i = 0; i < N; i++) {
            xId.put(xs[i], i);
            yId.put(ys[i], i);
        }

        int[] rx = new int[N];
        int[] cy = new int[N];
        for (int i = 0; i < N; i++) {
            rx[i] = xId.get(X[i]);
            cy[i] = yId.get(Y[i]);
        }

        // permutation: row index -> column index of rook
        int[] rowToCol = new int[N];
        int[] colToRow = new int[N];
        for (int i = 0; i < N; i++) {
            rowToCol[rx[i]] = cy[i];
            colToRow[cy[i]] = rx[i];
        }

        // active x-intervals / y-intervals
        boolean[] actX = new boolean[N + 1];
        boolean[] actY = new boolean[N + 1];
        actX[0] = actX[N] = true;
        actY[0] = actY[N] = true;
        for (int i = 1; i < N; i++) {
            actX[i] = xs[i] - xs[i - 1] >= 2;
            actY[i] = ys[i] - ys[i - 1] >= 2;
        }

        int[][] node = new int[N + 1][N + 1];
        for (int i = 0; i <= N; i++) Arrays.fill(node[i], -1);
        int cnt = 0;
        for (int i = 0; i <= N; i++) if (actX[i]) {
            for (int j = 0; j <= N; j++) if (actY[j]) {
                node[i][j] = cnt++;
            }
        }

        DSU dsu = new DSU(cnt);

        // Each rook connects opposite surrounding active regions diagonally.
        // If at least one surrounding region active on each side, union all active surrounding regions through this rook.
        ArrayList<int[]> around = new ArrayList<>(4);
        for (int r = 0; r < N; r++) {
            int a = rx[r], b = cy[r];
            around.clear();
            int[][] cand = {{a,b},{a+1,b},{a,b+1},{a+1,b+1}};
            for (int[] c : cand) {
                int id = node[c[0]][c[1]];
                if (id != -1) around.add(new int[]{c[0], c[1], id});
            }
            for (int i = 1; i < around.size(); i++) dsu.union(around.get(0)[2], around.get(i)[2]);
        }

        int[] compRooks = new int[cnt];
        for (int r = 0; r < N; r++) {
            int a = rx[r], b = cy[r];
            int rep = -1;
            int[][] cand = {{a,b},{a+1,b},{a,b+1},{a+1,b+1}};
            for (int[] c : cand) {
                int id = node[c[0]][c[1]];
                if (id != -1) { rep = dsu.find(id); break; }
            }
            if (rep != -1) compRooks[rep]++;
        }

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < N; i++) {
            int best = 1; // can always start on the chosen rook cell itself
            // If any adjacent safe region exists after removing this rook, or any immediate diagonal capture exists,
            // under the simplified component interpretation answer is size of reachable component + 1(start rook excluded from rooks count)
            int a = rx[i], b = cy[i];
            int comp = -1;
            int[][] cand = {{a,b},{a+1,b},{a,b+1},{a+1,b+1}};
            for (int[] c : cand) {
                int id = node[c[0]][c[1]];
                if (id != -1) {
                    comp = dsu.find(id);
                    break;
                }
            }
            if (comp != -1) best = 1 + compRooks[comp];
            out.append(best).append(' ').append(best - 1).append('\n');
        }

        System.out.print(out.toString());
    }
}

