static int cmp_x(const void *a, const void *b) {
    const Rook *A = (const Rook *)a;
    const Rook *B = (const Rook *)b;
    if (A->x < B->x) return -1;
    if (A->x > B->x) return 1;
    if (A->y < B->y) return -1;
    if (A->y > B->y) return 1;
    return 0;
}

static int cmp_y(const void *a, const void *b) {
    const Rook *A = (const Rook *)a;
    const Rook *B = (const Rook *)b;
    if (A->y < B->y) return -1;
    if (A->y > B->y) return 1;
    if (A->x < B->x) return -1;
    if (A->x > B->x) return 1;
    return 0;
}

static unsigned long long splitmix64(unsigned long long x) {
    x += 0x9e3779b97f4a7c15ULL;
    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL;
    x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL;
    return x ^ (x >> 31);
}

static ll pack_pair(ll a, ll b) {
    unsigned long long x = (unsigned long long)a;
    unsigned long long y = (unsigned long long)b;
    unsigned long long h = splitmix64(x + 0x9e3779b97f4a7c15ULL) ^ (splitmix64(y) << 1);
    return (ll)h;
}

static void hash_init(HashEntry **table, int *cap, int n) {
    *cap = 1;
    while (*cap < n * 4) *cap <<= 1;
    *table = (HashEntry *)calloc(*cap, sizeof(HashEntry));
}

static void hash_put(HashEntry *table, int cap, ll key, int val) {
    unsigned long long h = splitmix64((unsigned long long)key);
    int idx = (int)(h & (cap - 1));
    while (table[idx].used) {
        if (table[idx].key == key) {
            table[idx].val = val;
            return;
        }
        idx = (idx + 1) & (cap - 1);
    }
    table[idx].used = 1;
    table[idx].key = key;
    table[idx].val = val;
}

static int hash_get(HashEntry *table, int cap, ll key) {
    unsigned long long h = splitmix64((unsigned long long)key);
    int idx = (int)(h & (cap - 1));
    while (table[idx].used) {
        if (table[idx].key == key) return table[idx].val;
        idx = (idx + 1) & (cap - 1);
    }
    return -1;
}

